"""Aplica a identidade visual ao PBIP existente e preserva a pasta de dados."""
from pathlib import Path
import json
import base64

LOGO_BASE64 = ''
ROXO = '#4F008F'
ROXO_CLARO = '#F7F2FC'
TEXTO = '#32114F'
SCHEMA_VISUAL = 'https://developer.microsoft.com/json-schemas/fabric/item/report/definition/visualContainer/2.0.0/schema.json'

def literal(valor):
    if isinstance(valor, bool):
        texto = 'true' if valor else 'false'
    elif isinstance(valor, str):
        texto = "'" + valor.replace("'", "''") + "'"
    else:
        texto = str(valor) + 'D'
    return {'expr': {'Literal': {'Value': texto}}}

def cor(valor):
    return {'solid': {'color': literal(valor)}}

def gravar(arquivo, valor):
    arquivo.parent.mkdir(parents=True, exist_ok=True)
    arquivo.write_text(json.dumps(valor, ensure_ascii=False, indent=2), encoding='utf-8')

def trocar_cores(objeto):
    if isinstance(objeto, dict):
        return {k: trocar_cores(v) for k, v in objeto.items()}
    if isinstance(objeto, list):
        return [trocar_cores(v) for v in objeto]
    mapa = {
        '#16324F': ROXO, '#637488': '#655271',
        "'#16324F'": "'" + ROXO + "'",
        "'#637488'": "'#655271'"
    }
    return mapa.get(objeto, objeto) if isinstance(objeto, str) else objeto

def atualizar(pasta_projeto):
    projeto = Path(pasta_projeto)
    if projeto.suffix.lower() == '.pbip':
        atalho = json.loads(projeto.read_text(encoding='utf-8-sig'))
        report = projeto.parent / atalho['artifacts'][0]['report']['path']
    else:
        report = projeto / 'CantuStore.Report'
    definicao = report / 'definition'
    if not (definicao / 'report.json').is_file():
        raise FileNotFoundError('Selecione a pasta do projeto PBIP com CantuStore.Report/definition.')

    recursos = report / 'StaticResources' / 'RegisteredResources'
    recursos.mkdir(parents=True, exist_ok=True)
    (recursos / 'cantustore_logo.png').write_bytes(base64.b64decode(LOGO_BASE64))
    tema = {
        'name': 'CantuStore',
        'dataColors': [ROXO, '#8750C7', '#B188DD', '#6E18A8', '#CBB4E7', '#38105C', '#A067CF'],
        'background': '#FFFFFF', 'foreground': TEXTO, 'tableAccent': ROXO,
        'textClasses': {
            'title': {'fontFace': 'Segoe UI', 'color': ROXO},
            'label': {'fontFace': 'Segoe UI', 'color': TEXTO},
            'callout': {'fontFace': 'Segoe UI', 'color': ROXO}
        }
    }
    gravar(recursos / 'CantuStoreTheme.json', tema)
    arquivo = definicao / 'report.json'
    meta = json.loads(arquivo.read_text(encoding='utf-8-sig'))
    meta.setdefault('themeCollection', {})['customTheme'] = {
        'name': 'CantuStoreTheme.json', 'reportVersionAtImport': '5.55',
        'type': 'RegisteredResources'
    }
    pacotes = meta.setdefault('resourcePackages', [])
    pacote = next((p for p in pacotes if p['name'] == 'RegisteredResources'), None)
    if pacote is None:
        pacote = {'name': 'RegisteredResources', 'type': 'RegisteredResources', 'items': []}
        pacotes.append(pacote)
    for nome, tipo in [('cantustore_logo.png', 'Image'), ('CantuStoreTheme.json', 'CustomTheme')]:
        pacote['items'] = [i for i in pacote['items'] if i['name'] != nome]
        pacote['items'].append({'name': nome, 'path': nome, 'type': tipo})
    gravar(arquivo, meta)

    total_paginas = 0
    for arquivo_pagina in (definicao / 'pages').glob('*/page.json'):
        total_paginas += 1
        pagina = json.loads(arquivo_pagina.read_text(encoding='utf-8-sig'))
        pagina.setdefault('objects', {})['background'] = [
            {'properties': {'color': cor(ROXO_CLARO), 'transparency': literal(0)}}
        ]
        gravar(arquivo_pagina, pagina)
        for arquivo_visual in (arquivo_pagina.parent / 'visuals').glob('*/visual.json'):
            visual = trocar_cores(json.loads(arquivo_visual.read_text(encoding='utf-8-sig')))
            if visual.get('name') == 'cantustore_logo':
                continue
            conteudo = visual.get('visual', {})
            tipo = conteudo.get('visualType')
            container = conteudo.setdefault('visualContainerObjects', {})
            objetos = conteudo.setdefault('objects', {})
            container['border'] = [{'properties': {
                'show': literal(tipo != 'textbox'),
                'color': cor('#E4D6F0'), 'radius': literal(10), 'width': literal(1)
            }}]
            if tipo == 'textbox':
                textos = objetos.get('general', [{}])[0].get('properties', {}).get('paragraphs', [])
                if visual['position']['y'] < 100:
                    container['background'] = [{'properties': {
                        'show': literal(True), 'color': cor(ROXO), 'transparency': literal(0)
                    }}]
                    container['border'][0]['properties']['show'] = literal(True)
                    container['border'][0]['properties']['color'] = cor(ROXO)
                    for paragrafo in textos:
                        for run in paragrafo.get('textRuns', []):
                            run.setdefault('textStyle', {})['color'] = '#FFFFFF'
                elif visual['position']['y'] >= 900:
                    visual['position']['x'] = 116
                    visual['position']['width'] = 1452
            else:
                container['background'] = [{'properties': {
                    'show': literal(True), 'color': cor('#FFFFFF'), 'transparency': literal(0)
                }}]
                if tipo in ('clusteredBarChart', 'lineChart'):
                    objetos['dataPoint'] = [{'properties': {'defaultColor': cor(ROXO)}}]
                if tipo == 'card':
                    objetos.setdefault('labels', [{'properties': {}}])[0]['properties']['color'] = cor(ROXO)
                if tipo == 'tableEx':
                    objetos['columnHeaders'] = [{'properties': {
                        'fontSize': literal(11), 'fontColor': cor('#FFFFFF'),
                        'backColor': cor(ROXO)
                    }}]
                    objetos['values'] = [{'properties': {
                        'fontSize': literal(11), 'fontColor': cor(TEXTO),
                        'backColor': cor('#FFFFFF'), 'backColorSecondary': cor(ROXO_CLARO)
                    }}]
            gravar(arquivo_visual, visual)
        logo = {
            '$schema': SCHEMA_VISUAL, 'name': 'cantustore_logo',
            'position': {'x': 32, 'y': 922, 'width': 64, 'height': 64, 'z': 999, 'tabOrder': 999},
            'visual': {
                'visualType': 'image',
                'objects': {'general': [{'properties': {
                    'imageUrl': {'expr': {'ResourcePackageItem': {
                        'PackageName': 'RegisteredResources', 'PackageType': 1,
                        'ItemName': 'cantustore_logo.png'
                    }}},
                    'imageScaling': literal('Normal')
                }}]},
                'visualContainerObjects': {
                    'title': [{'properties': {'show': literal(False)}}],
                    'background': [{'properties': {'show': literal(False)}}],
                    'border': [{'properties': {'show': literal(False)}}]
                }
            }
        }
        gravar(arquivo_pagina.parent / 'visuals/cantustore_logo/visual.json', logo)
    print(f'Identidade visual aplicada em {total_paginas} páginas.')
    print('Abra novamente o projeto no Power BI Desktop.')
    print('Os nomes reais dos produtos dependem de um cadastro produto_id / nome_produto.')

if __name__ == '__main__':
    atualizar(Path(__file__).resolve().parent)
